#include <atomic>

template <class T>
class HazardPtr {
    std::atomic<void*> slot_{nullptr};
public:
    // guard pattern: publish, verify, and release on every exit including throw
    T* protect(const std::atomic<T*>& src) {
        for (;;) {
            T* p = src.load(std::memory_order_acquire);
            slot_.store(p, std::memory_order_seq_cst);     // publish first
            std::atomic_thread_fence(std::memory_order_seq_cst);  // then verify
            if (p == src.load(std::memory_order_acquire)) return p;
        }
    }
    ~HazardPtr() { slot_.store(nullptr, std::memory_order_seq_cst); }
};

// the scope guard means an exception cannot leak a hazard record
// std::atomic<T>::wait / notify_one give the reclamation layer a blocking interface
